style.css:
@-moz-document domain("ioe.vn") {
/* General Settings */
  body {
    background: linear-gradient(120deg, #1e1e2f, #2b2b40);
    color: #ffffff;
    font-family: 'Poppins', sans-serif;
    line-height: 1.6;
    margin: 0;
    transition: all 0.3s ease-in-out;
  }

  /* Links */
  a {
    color: #4caf50;
    text-decoration: none;
    font-weight: bold;
    transition: color 0.2s ease-in-out;
  }

  a:hover {
    color: #81c784;
  }

  /* Headers */
  h1, h2, h3, h4, h5, h6 {
    color: #ffd54f;
    margin: 10px 0;
    line-height: 1.2;
  }

  /* Buttons */
  button, .btn {
    background-color: #4caf50;
    color: #ffffff;
    border: none;
    padding: 10px 20px;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    transition: background-color 0.3s, transform 0.2s ease-in-out;
  }

  button:hover, .btn:hover {
    background-color: #81c784;
    transform: translateY(-1px);
  }

  /* Inputs */
  input, textarea {
    background-color: #2b2b40;
    color: #ffffff;
    border: 1px solid #4caf50;
    padding: 8px 12px;
    border-radius: 4px;
    outline: none;
    font-size: 1rem;
    transition: border-color 0.3s ease;
  }

  input:focus, textarea:focus {
    border-color: #81c784;
  }

  /* Navigation Bar */
  .navbar {
    background-color: #1e1e2f;
    border-bottom: 2px solid #4caf50;
  }

  .navbar a {
    color: #ffd54f;
    padding: 10px 15px;
    font-size: 1rem;
    transition: background-color 0.3s ease-in-out;
  }

  .navbar a:hover {
    background-color: #2b2b40;
  }

  /* Footer */
  footer {
    background-color: #1e1e2f;
    color: #a8a8a8;
    text-align: center;
    padding: 20px;
    font-size: 0.9rem;
  }

  footer a {
    color: #4caf50;
  }

  footer a:hover {
    color: #81c784;
  }

  /* Cards and Containers */
  .card, .box {
    background-color: #2b2b40;
    border-radius: 8px;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.2);
    padding: 20px;
    margin-bottom: 20px;
    color: #ffffff;
  }

  .card:hover, .box:hover {
    box-shadow: 0 6px 8px rgba(0, 0, 0, 0.3);
  }

  /* Tables */
  table {
    width: 100%;
    border-collapse: collapse;
    background-color: #2b2b40;
    color: #ffffff;
  }

  table th, table td {
    padding: 10px;
    border: 1px solid #4caf50;
    text-align: left;
  }

  table th {
    background-color: #4caf50;
    color: #ffffff;
  }

  table tr:nth-child(even) {
    background-color: #2e2e42;
  }

  table tr:hover {
    background-color: #3b3b52;
  }

  /* Animations */
  @keyframes fadeIn {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }

  .animated {
    animation: fadeIn 0.8s ease-in-out;
  }

  /* Misc */
  .highlight {
    background-color: #ffd54f;
    color: #1e1e2f;
    padding: 5px 10px;
    border-radius: 4px;
    font-weight: bold;
  }
}
